// Menu source watermark: @use_sberbank
#pragma once

#include <cstdint>

#include "imgui.h"

// Items of the Inventory tab. The tables are generated by tools/build_inventory.py; the images
// they point to are packed into assets/images/inventory.pak (see menu/images.h).
namespace nl::inv {

enum class Kind : std::uint8_t { pistol, mid_tier, rifle, zeus, knife, gloves, agent, medal, music_kit };

inline constexpr std::uint8_t team_ct = 1;
inline constexpr std::uint8_t team_t = 2;

// Chams of a slot's own model (SlotFinish::model_material), and the chams material type of
// the cheat core each one draws with; -1 is off.
inline constexpr const char* k_model_materials[] = { "Disabled", "Shaded", "Solid", "Glow",
                                                     "Glow Outline", "Iridescent", "Water Flow", "Glossy" };
inline constexpr int k_model_material_type[] = { -1, 1, 0, 2, 3, 4, 5, 6 };

struct Rarity {
    const char* name;
    ImU32 color;
};

// A PNG in the pak. The PNG holds the opaque part (x, y, w, h) of a canvas_w x canvas_h picture.
struct Image {
    std::uint32_t offset;
    std::uint32_t size;
    std::uint16_t x, y, w, h;
    std::uint16_t canvas_w, canvas_h;
};

struct Item {
    const char* name;       // finish ("Fade"), or the full name for agents, medals and music kits
    const char* collection; // may be null
    std::uint8_t rarity;    // index into rarities, which are sorted from common to rare
    std::int16_t image;
    std::int16_t collection_icon; // -1 if none
    std::int16_t body;            // full-body render for agents, -1 if none
};

// A weapon (or knife type, glove type, agent list...) and its items. When has_default is set,
// the first item is the stock look ("No Skin").
struct Weapon {
    const char* name;
    Kind kind;
    std::uint8_t teams;
    std::int16_t first_item;
    std::int16_t item_count;
    bool has_default;
};

enum Slot : int {
    slot_pistol = 0, // 5 slots
    slot_mid_tier = 5,
    slot_rifle = 10,
    slot_agent = 15,
    slot_medal,
    slot_music_kit,
    slot_knife,
    slot_gloves,
    slot_zeus,
    slot_count,
};

struct Equip {
    std::int16_t weapon;
    std::int16_t item; // index into items
};

extern const Rarity rarities[];
extern const int rarity_count;
extern const Image images[];
extern const int image_count;
extern const Item items[];
extern const int item_count;
extern const Weapon weapons[];
extern const int weapon_count;
extern const Equip default_loadouts[2][slot_count]; // [0] = CT, [1] = T

// CS2 identifiers (tools/build_skin_ids.py). Indexed exactly like the tables above; 0
// means "no identifier", which the skinchanger treats as unskinnable.
extern const std::uint16_t item_paint_kit[];
extern const int item_paint_kit_count;
extern const std::uint16_t weapon_def_index[];
extern const int weapon_def_index_count;


extern const int sticker_images[3];
extern const int charm_image;
extern const int players_preview_image;

} // namespace nl::inv
